1	import { ContactRow, PersonRow, ProgramRoleAssignmentRow } from "@cyc-seattle/crm";
2	import { CampRow, ClassRow, RegistrationEntryRow, RegistrationRow } from "@cyc-seattle/clubspot";
3	import { isCampInMembershipWindow } from "./camps.js";
4	
5	/**
6	 * Whether a `program_role_assignments` row is in effect on `now`. Durable by default: a null
7	 * `starts_on` or `ends_on` is unbounded on that side, so no dates at all means current forever.
8	 */
9	export function isCurrentProgramRole(row: Pick<ProgramRoleAssignmentRow, "starts_on" | "ends_on">, now: Date): boolean {
10	  const started = row.starts_on == null || new Date(row.starts_on) <= now;
11	  const notEnded = row.ends_on == null || new Date(row.ends_on) >= now;
12	  return started && notEnded;
13	}
14	
15	/** The rows a program-group membership plan reads. See `run.ts` for where these come from. */
16	export interface MembershipTables {
17	  classes: readonly ClassRow[];
18	  camps: readonly CampRow[];
19	  registrationEntries: readonly RegistrationEntryRow[];
20	  registrations: readonly RegistrationRow[];
21	  people: readonly PersonRow[];
22	  contacts: readonly ContactRow[];
23	  programRoleAssignments: readonly ProgramRoleAssignmentRow[];
24	}
25	
26	export interface PlanProgramMembersOptions {
27	  /** Skip the camp membership window so every class contributes its participants regardless of
28	   * how long ago its camp ended - the "unwindowed" plan the audit compares stale membership
29	   * against (see `audit.ts`'s `plannedGroupMembers`). Role assignments are never subject to this
30	   * window either way, so this option has no effect on them. */
31	  ignoreCampWindow?: boolean;
32	}
33	
34	function normalizeEmail(email: string): string {
35	  return email.trim().toLowerCase();
36	}
37	
38	/**
39	 * Whether an address is plausibly deliverable. Clubspot contact fields hold phone numbers, bare
40	 * surnames and typos, and the Directory API rejects the whole add on one bad `memberKey`, so these
41	 * are skipped here and reported by the audit's `invalid_email` finding instead.
42	 */
43	export function isValidEmail(email: string): boolean {
44	  return /^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(email.trim()) && !email.includes("..");
45	}
46	
47	function addEmail(emails: Set<string>, raw: string): void {
48	  if (isValidEmail(raw)) {
49	    emails.add(normalizeEmail(raw));
50	  }
51	}
52	
53	/**
54	 * The people `planProgramMembers` draws its emails from - participants, their guardians, and
55	 * current role holders - before any email is checked. The audit uses this to report the unusable
56	 * addresses that are actually keeping someone out of a group, and nobody else.
57	 */
58	export function planProgramMemberPeople(
59	  programId: string,
60	  tables: MembershipTables,
61	  now: Date,
62	  options: PlanProgramMembersOptions = {},
63	): PersonRow[] {
64	  const campById = new Map(tables.camps.filter((row) => row.id).map((row) => [row.id as string, row]));
65	  const classIds = new Set(
66	    tables.classes
67	      .filter((cls) => cls.program_id === programId)
68	      .filter((cls) => {
69	        if (options.ignoreCampWindow) {
70	          return true;
71	        }
72	        const camp = campById.get(cls.camp_id);
73	        return camp != null && isCampInMembershipWindow(camp, now);
74	      })
75	      .map((cls) => cls.id),
76	  );
77	  const registrationById = new Map(tables.registrations.filter((row) => row.id).map((row) => [row.id as string, row]));
78	  const personById = new Map(tables.people.filter((row) => row.id).map((row) => [row.id as string, row]));
79	
80	  const participantIds = new Set(
81	    tables.registrationEntries
82	      .filter((entry) => classIds.has(entry.class_id) && entry.status === "confirmed")
83	      .map((entry) => registrationById.get(entry.registration_id)?.person_id)
84	      .filter((personId): personId is string => personId != null),
85	  );
86	
87	  const people = new Map<string, PersonRow>();
88	  const include = (personId: string): void => {
89	    const person = personById.get(personId);
90	    if (person?.id && person.email) {
91	      people.set(person.id, person);
92	    }
93	  };
94	
95	  for (const participantId of participantIds) {
96	    include(participantId);
97	    for (const contact of tables.contacts) {
98	      if (contact.subject_id === participantId && contact.relationship_type === "guardian") {
99	        include(contact.contact_id);
100	      }
101	    }
102	  }
103	
104	  for (const assignment of tables.programRoleAssignments) {
105	    if (assignment.program_id === programId && isCurrentProgramRole(assignment, now)) {
106	      include(assignment.person_id);
107	    }
108	  }
109	
110	  return [...people.values()];
111	}
112	
113	/**
114	 * The member emails one program's Google Group should have: participants with a confirmed
115	 * `registration_entries` row for one of the program's classes (`classes.program_id`), their
116	 * guardians, the participant's own email when set - which is what makes an adult with no guardian
117	 * row work with no special case - and every person with a current `program_role_assignments` row
118	 * for the program. Every role grants plain `MEMBER`; there's no separate manager mapping. Never
119	 * emergency contacts. Deduped by lowercased, trimmed email, since a family commonly shares one.
120	 *
121	 * Add-only: this is never diffed against live membership. The executor adds every email this
122	 * returns and treats "already a member" as success (see `DirectoryClient.addMember`), so someone
123	 * removed from `registration_entries` or `program_role_assignments` simply stops being re-added -
124	 * they're never removed here.
125	 *
126	 * A class only contributes participants when its camp is within the membership window (see
127	 * `isCampInMembershipWindow`), unless `options.ignoreCampWindow` is set - a class whose camp can't
128	 * be found at all doesn't contribute either, the same as a camp outside the window. Role
129	 * assignments are never subject to this window; they have their own `starts_on`/`ends_on` filter
130	 * and must keep working for a program with no live camp at all (#149).
131	 */
132	export function planProgramMembers(
133	  programId: string,
134	  tables: MembershipTables,
135	  now: Date,
136	  options: PlanProgramMembersOptions = {},
137	): string[] {
138	  const emails = new Set<string>();
139	  for (const person of planProgramMemberPeople(programId, tables, now, options)) {
140	    addEmail(emails, person.email as string);
141	  }
142	  return [...emails].sort();
143	}
144

import { CampRow } from "@cyc-seattle/clubspot";

/**
 * How far back a camp's `end_date` can fall and still contribute participants to its program's
 * group (#149). ~12 months, so a just-finished season's roster stays in place until the next one
 * begins, rather than the group emptying out between seasons.
 */
const MEMBERSHIP_WINDOW_MS = 365 * 24 * 60 * 60 * 1000;

/**
 * Whether a camp is still within the membership window: running, upcoming, or ended recently
 * enough (see `MEMBERSHIP_WINDOW_MS`). Governs which classes contribute participants to a
 * program's group in `planProgramMembers` - it does not gate whether the program's task gets
 * enqueued at all (see `enqueueDueProgramGroups`), and it plays no part in a person already added
 * ever being removed (add-only).
 */
export function isCampInMembershipWindow(camp: Pick<CampRow, "end_date">, now: Date): boolean {
  if (camp.end_date == null) {
    return true;
  }
  return new Date(camp.end_date).getTime() >= now.getTime() - MEMBERSHIP_WINDOW_MS;
}

